// Types for build/plugin-api/*.v1.json from slack-datamine-plus (generated by src/plugin-api.mjs). Schema version 1.

/** A defining webpack module as "id:hash" (hash: first 8 hex chars of a sha1 of the module's code; changes with any edit). */
export type ModuleRef = `${string}:${string}`;

interface Envelope<K extends string> {
  $schema?: string;
  schemaVersion: 1;
  kind: K;
  /** Slack build the data was mined from */
  build: string | null;
  /** YYYY-MM-DD */
  capturedDate: string | null;
  count: number;
}

export interface Component {
  /** up to 3 */
  modules: ModuleRef[];
}

export interface ComponentsV1 extends Envelope<'components'> {
  /** React components by displayName */
  components: Record<string, Component>;
}

export type ReduxKind = 'thunk' | 'selector' | 'action' | 'fetcher' | 'middleware' | 'reducer';

export interface ReduxEntry<K extends ReduxKind = ReduxKind> {
  kind: K;
  name: string;
  /** internal key, e.g. "createThunkFoo" */
  key: string;
  description?: string;
  /** up to 3 */
  modules: ModuleRef[];
}

export interface ReduxV1 extends Envelope<'redux'> {
  /** keyed "<kind>:<name>" */
  redux: { [id: `${ReduxKind}:${string}`]: ReduxEntry };
}
